    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Expected values variables for checking
    reg [3:0] exp_ones;
    reg [3:0] exp_tens;
    reg [3:0] exp_hundreds;
    reg [3:0] exp_thousands;
    reg [3:0] exp_ena;
    reg [15:0] exp_q;

    initial begin
        clk = 0;
        reset = 1;

        // Initialize expected tracking
        exp_ones = 4'd0;
        exp_tens = 4'd0;
        exp_hundreds = 4'd0;
        exp_thousands = 4'd0;

        // Apply reset
        @(posedge clk);
        #1;
        reset = 1;
        @(posedge clk);
        #1;

        // Check reset state
        exp_q = {exp_thousands, exp_hundreds, exp_tens, exp_ones};
        exp_ena = 4'b0000; // specific enable check if needed, typically active when lower digits wrap

        if (q !== exp_q) begin
            $display("Time %0t: Reset error! q = %h, expected %h", $time, q, exp_q);
            errors = errors + 1;
        end

        // Deassert reset
        reset = 0;
        @(posedge clk);

        // Run through enough cycles to test rollover and enables
        // We'll test up past 9999 or check key rollover points to keep stimulus concise.
        // Let's run a loop for 105 cycles to test ones digit rollovers and tens enable.
        for (i = 0; i < 110; i = i + 1) begin
            // Calculate expected next state BEFORE the clock edge (or reference previous)
            // Determine expected enables based on current state before increment
            // Ena[0] (for tens) active when ones == 9
            // Ena[1] (for hundreds) active when tens == 9 and ones == 9
            // Ena[2] (for thousands) active when hundreds == 9, tens == 9, and ones == 9

            // Wait for setup before clk edge to compute expected enables correctly
            // Actually, let's verify on posedge after outputs update, comparing against software model step.

            @(posedge clk);
            #1; // allow propagation

            // Software model update (Post-increment emulation)
            if (exp_ones == 4'd9) begin
                exp_ones = 4'd0;
                if (exp_tens == 4'd9) begin
                    exp_tens = 4'd0;
                    if (exp_hundreds == 4'd9) begin
                        exp_hundreds = 4'd0;
                        if (exp_thousands == 4'd9) begin
                            exp_thousands = 4'd0;
                        end else begin
                            exp_thousands = exp_thousands + 1;
                        end
                    end else begin
                        exp_hundreds = exp_hundreds + 1;
                    end
                end else begin
                    exp_tens = exp_tens + 1;
                end
            end else begin
                exp_ones = exp_ones + 1;
            end

            exp_q = {exp_thousands, exp_hundreds, exp_tens, exp_ones};

            if (q !== exp_q) begin
                $display("Time %0t: Mismatch! q = %h (thousands:%d, hundreds:%d, tens:%d, ones:%d), expected %h", 
                         $time, q, q[15:12], q[11:8], q[7:4], q[3:0], exp_q);
                errors = errors + 1;
            end
        end

        // Test synchronous reset again mid-operation
        reset = 1;
        exp_ones = 4'd0;
        exp_tens = 4'd0;
        exp_hundreds = 4'd0;
        exp_thousands = 4'd0;

        @(posedge clk);
        #1;
        exp_q = 16'h0000;
        if (q !== exp_q) begin
            $display("Time %0t: Mid-op Reset error! q = %h", $time, q);
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;

        // Final Result Display
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
